#include "instaham/cutter/ShoulderSelectorV176.hpp"
#include "instaham/MaskUtils.hpp"
#include <algorithm>
#include <cmath>
#include <vector>
namespace instaham { namespace {
constexpr double PE=1e-12, TOUCH=1e-6, MEET=.5;
struct Cross{double x;};
double interp(const std::vector<double>&a,double x){if(a.empty())return nanValue();x=std::clamp(x,0.0,double(a.size()-1));int i=floor(x),j=ceil(x);if(i==j)return a[i];double f=x-i;return a[i]*(1-f)+a[j]*f;}
std::vector<Cross> crosses(const std::vector<double>&d){std::vector<Cross>e;for(int i=0;i+1<(int)d.size();i++){double a=d[i],b=d[i+1];if(!std::isfinite(a)||!std::isfinite(b))continue;if(abs(a)<=TOUCH)e.push_back({double(i)});if(a*b<0)e.push_back({i+(-a)/(b-a)});else if(abs(b)<=TOUCH)e.push_back({double(i+1)});}std::sort(e.begin(),e.end(),[](auto&a,auto&b){return a.x<b.x;});std::vector<Cross>c;for(auto&e0:e)if(c.empty()||abs(e0.x-c.back().x)>1e-9)c.push_back(e0);return c;}
std::vector<double> maxima(const std::vector<double>&b){std::vector<double>p;for(int i=1;i+1<(int)b.size();i++)if(std::isfinite(b[i-1])&&std::isfinite(b[i])&&std::isfinite(b[i+1])&&b[i]>b[i-1]&&b[i]>b[i+1])p.push_back(i);return p;}
bool breakMeet(const std::vector<double>&b,const std::vector<double>&o,double x){std::vector<double>d(b.size());for(size_t i=0;i<b.size();i++)d[i]=b[i]-o[i];x=std::clamp(x,0.0,double(b.size()-1));double id=interp(d,x);int f=floor(x),c=ceil(x);if(std::isfinite(id)&&abs(id)<=MEET)return true;if(c!=f&&std::isfinite(d[f])&&std::isfinite(d[c])&&d[f]*d[c]<0)return true;if(c!=f&&((std::isfinite(d[f])&&abs(d[f])<=MEET)||(std::isfinite(d[c])&&abs(d[c])<=MEET)))return true;return false;}
}
ShoulderDecision selectShoulderV176(const OrientedTrunk&t,const Break1Result&fit){ShoulderDecision r;if(!fit.valid||t.radii.empty()||fit.predictionReal.size()!=t.radii.size())return r;auto&b=t.radii;auto&o=fit.predictionReal;int n=b.size();double break1=std::clamp(fit.break1Real,0.0,double(n-1)),limit=(1.0/3.0)*std::max(n-1,0);std::vector<double>d(n);for(int i=0;i<n;i++)d[i]=b[i]-o[i];auto cr=crosses(d);auto all=maxima(b);std::vector<double>primary;for(double p:all){int i=roundEvenInt(p);if(p>break1+PE&&p<limit-PE&&b[i]>o[i])primary.push_back(p);}double cutoff=nanValue();if(limit>break1+PE&&limit>PE){double bl=interp(b,limit),ol=interp(o,limit);double lx=abs(limit-round(limit))<=PE?(round(limit)>=1?round(limit)-1:-1):floor(limit);if(lx>=0&&bl>interp(b,lx)&&bl>ol)cutoff=limit;}
 std::vector<int>primaryIdx;for(double p:primary)primaryIdx.push_back(roundEvenInt(p));std::vector<double>non;for(double p:all){if(!(p>PE&&p<limit-PE))continue;if(std::find(primaryIdx.begin(),primaryIdx.end(),roundEvenInt(p))==primaryIdx.end())non.push_back(p);}auto highest=[&](const std::vector<double>&p)->double{if(p.empty())return nanValue();return *std::max_element(p.begin(),p.end(),[&](double a,double z){auto ka=std::pair<double,double>(interp(b,a),a),kz=std::pair<double,double>(interp(b,z),z);return ka<kz;});};double highNon=highest(non);std::vector<double>leftPeaks;for(double p:all)if(p<break1-PE)leftPeaks.push_back(p);double highLeft=highest(leftPeaks);double selected=break1;std::string reason,cas;
 if(!primary.empty()){cas="PRIMARY_REAL_PEAK_ROUTE";double p1=*std::min_element(primary.begin(),primary.end());std::vector<std::pair<double,bool>>body;for(double p:primary)if(p>p1+PE)body.push_back({p,false});if(std::isfinite(cutoff)&&cutoff>p1+PE)body.push_back({cutoff,true});double governing=p1;if(!body.empty()){auto p2=*std::min_element(body.begin(),body.end(),[](auto&a,auto&z){return a.first<z.first;});if(!p2.second&&interp(b,p2.first)>interp(b,p1))governing=p2.first;}if(std::isfinite(highNon)&&interp(b,highNon)>interp(b,governing)){selected=highNon;reason="primary lower than highest strict non-primary";}else{bool found=false;double near=-1e300;for(auto&e:cr)if(e.x<governing-PE&&e.x>near){near=e.x;found=true;}if(found){selected=near;reason="headward intersection of governing primary";}else{selected=governing;reason="no headward intersection; governing primary";}}}
 else {cas="NO_REAL_PRIMARY_FALLBACK";if(breakMeet(b,o,break1)){selected=break1;reason="break1 region meet";}else{std::vector<double>left;for(auto&e:cr)if(e.x<break1-PE)left.push_back(e.x);std::sort(left.begin(),left.end());if(left.size()>=2){selected=left[1];reason="second from HEAD left intersection";}else if(left.size()==1){selected=left[0];reason="only left intersection";}else if(std::isfinite(highLeft)){selected=highLeft;reason="highest actual completed BLUE peak left of break1";}else{selected=break1;reason="forced break1 fallback";}}}
 r.valid=true;r.cutRequired=true;r.break1X=break1;r.selectedX=selected;r.selectedPos=std::clamp(roundEvenInt(selected),0,n-1);r.caseName=cas;r.reason=reason;return r;}
}
